import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * All amounts are formatted using formatEuros().
 * @param {Object} invoice
 * @param {Object} customer - Customer object with at least a 'name' property
 * @returns {string}
 */
export function renderInvoiceText(invoice, customer) {
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number || 'DRAFT');

  // Customer name
  lines.push(customer.name);

  // Invoice lines with discount info
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const totalFormatted = formatEuros(total);
    let lineStr = `${line.qty} × ${line.name} ${unitPriceFormatted} ${totalFormatted}`;

    // Add discount if line has one
    const discount = lineDiscount(line);
    if (discount > 0) {
      const discountFormatted = formatEuros(discount);
      lineStr += ` (−${discountFormatted})`;
    }

    lines.push(lineStr);
  }

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // VAT line (if there's any VAT)
  if (totals.vat > 0) {
    const vatFormatted = formatEuros(totals.vat);
    lines.push(`VAT: ${vatFormatted}`);
  }

  // Voucher line (if there's a voucher)
  if (invoice.voucher) {
    const voucherFormatted = formatEuros(invoice.voucher.amount);
    lines.push(`Voucher: −${voucherFormatted}`);
  }

  // Total line
  const totalFormatted = formatEuros(totals.total);
  lines.push(`Total: ${totalFormatted}`);

  // Due date line (if invoice has one)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid line (if invoice has payments)
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    const paidFormatted = formatEuros(totalPaid);
    lines.push(`Paid: ${paidFormatted}`);
  }

  return lines.join('\n');
}

