  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText complete invoice with all elements', () => {
  const invoice = {
    number: 'INV-2024-0001',
    customerId: 'C-001',
    issueDate: '2024-10-15',
    dueDate: '2024-11-14',
    status: 'partially_paid',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
    ],
    voucher: { code: 'PROMO', amount: 5000 },
    payments: [{ amount: 30000, date: '2024-10-20' }],
  };

  const customer = { id: 'C-001', name: 'Acme Corp', email: 'hello@acme.example' };

  const text = renderInvoiceText(invoice, customer);
